    43  	/**
    44  	 * Constructor for the session class.
    45  	 */
    46  	public function __construct() {
    47  		$this->token = wc_clean( wp_unslash( $_SERVER['HTTP_CART_TOKEN'] ?? '' ) );
    48  		$this->table = $GLOBALS['wpdb']->prefix . 'woocommerce_sessions';
    49  	}
